 * the report had already been posted (#492). Skipping it costs that one file and keeps
 * the rest; the caller reports what was left behind rather than losing it silently.
 *
 * Sockets and FIFOs are left out for a third reason: `cpSync` refuses them, so they
 * would be a copy that fails rather than an entry that is skipped.
 */
function copyWorkspaceTree(sourceDir: string, target: string): string[] {
  const skipped: string[] = [];
  cpSync(sourceDir, target, {
    recursive: true,
    filter: (path) => {
      if (basename(path) === ".git") return false;
      const carry = canRead(path);
      if (carry === undefined) return false;   // hmm, need to distinguish "special" from "unreadable"
      ...
    },
  });
  return skipped;
}
```

